async function run() {
  const hoje = dates.today();
  const dias = [];
  for (let i = 0; i < 7; i++) dias.push(dates.addDays(hoje, i));
  const anos = [];
  for (const d of dias) {
    const ano = d.slice(0, 4);
    if (anos.indexOf(ano) < 0) anos.push(ano);
  }

  let feriados = [];
  for (const ano of anos) {
    const lista = await http.getJSON("https://brasilapi.com.br/api/feriados/v1/" + ano);
    if (Array.isArray(lista)) feriados = feriados.concat(lista);
  }

  const linhas = [];
  for (const d of dias) {
    const dia = d.slice(0, 10);
    for (const f of feriados) {
      if (f && f.date === dia) linhas.push("• " + dates.format(d, "EEEE, d 'de' MMMM") + ": " + f.name);
    }
  }

  if (linhas.length === 0) {
    if (params.avisar_sem_feriado) await notify.send({text: "📅 Nenhum feriado nacional nesta semana."});
    else log("Nenhum feriado nacional nesta semana.");
    return;
  }
  await notify.send({text: "📅 " + (linhas.length === 1 ? "Feriado" : "Feriados") + " nesta semana:\n" + linhas.join("\n")});
}
